#!/usr/bin/env bash
set -euo pipefail

cd ~/freddy-fixit
rm -f .git/index.lock 2>/dev/null || true

echo ""
echo "Freddy Fix It — navy comes back to light mode"
echo "---------------------------------------------"
echo ""

# Decode into /tmp first and only copy onto the real path once the byte count
# matches. A redirect straight onto the destination truncates it BEFORE the
# command runs, which is how ClientDashboard.tsx was wiped.
write_file() {
  path="$1"; want="$2"
  mkdir -p "$(dirname "$path")"
  base64 -d < /tmp/ff_b64 > /tmp/ff_out
  got=$(wc -c < /tmp/ff_out | tr -d ' ')
  if [ "$got" != "$want" ]; then
    echo "  X $path decoded $got bytes, expected $want"
    echo "  Nothing was written. Send this message to Claude."
    exit 1
  fi
  cp /tmp/ff_out "$path"
  echo "  ok  $path  ($got bytes)"
}

echo "Writing files..."

