write_file "CLAUDE.md" 94174

rm -f /tmp/ff_b64 /tmp/ff_out

echo ""
echo "Type-checking (this is what catches an empty module — vite build cannot)..."
npm install --silent
npm run typecheck

echo ""
echo "Building..."
npx vite build

echo ""
echo "Pushing..."
# A scratch before/after preview got written into the folder while building
# this. The sandbox can't delete from the mount, so it's cleaned here instead
# — otherwise `git add -A` would commit it to the PUBLIC repo.
rm -f light-mode-preview.html
git add -A
git commit -m "Light mode: put navy back in it. Add the .ff-on-dark scope class and mount it on the nav, hero and footer so the 30 of 60/30/10 is brand colour instead of a second white"
git push

echo ""
echo "OK - pushed. Vercel is deploying now."
echo "Wait ~60s, then hard-refresh with Cmd+Shift+R."
echo ""
